<script setup lang="ts">
import SelectField from '../../Components/SelectField.vue';
import {ref,nextTick,onBeforeUnmount} from 'vue';import {Head,Link,router,useForm,usePage} from '@inertiajs/vue3';import {Wallet,LoaderCircle} from 'lucide-vue-next';import ConfirmDialog from '../../Components/ConfirmDialog.vue';import SetupLayout from '../../Layouts/SetupLayout.vue';
const page=usePage<any>();const form=useForm({name:'',nickname:page.props.auth?.name?.split(' ')[0]||'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});const errors=ref<HTMLElement>(),discard=ref(false);let pending:any,leaving=false,saving=false;
const timezones=Intl.supportedValuesOf('timeZone').map(value=>({value,label:value.replaceAll('_',' ')}));if(!timezones.some(option=>option.value===form.timezone))timezones.unshift({value:form.timezone,label:form.timezone});
function save(){form.clearErrors();if(!form.name.trim())form.setError('name','Enter a household name.');if(!form.nickname.trim())form.setError('nickname','Enter your nickname.');try{new Intl.DateTimeFormat('en-US',{timeZone:form.timezone});}catch{form.setError('timezone','Enter a valid timezone.');}if(form.hasErrors){nextTick(()=>errors.value?.focus());return;}saving=true;form.post('/setup/household',{onFinish:()=>saving=false,onError:()=>nextTick(()=>errors.value?.focus()),onSuccess:()=>leaving=true,onNetworkError:()=>{form.setError('name','Could not save. Your values are still here; try again.');return false;}});}
function blur(field:'name'|'nickname'|'timezone'){if(field==='timezone'){try{new Intl.DateTimeFormat('en-US',{timeZone:form.timezone});form.clearErrors(field);}catch{form.setError(field,'Enter a valid timezone.');}}else if(!form[field].trim())form.setError(field,field==='name'?'Enter a household name.':'Enter your nickname.');else form.clearErrors(field);}
const stop=router.on('before',event=>{if(!form.isDirty||form.processing||saving||leaving)return;event.preventDefault();pending=event.detail.visit;discard.value=true;});onBeforeUnmount(stop);
function leave(){discard.value=false;leaving=true;router.visit(pending.url,pending);}
</script>
<template><SetupLayout narrow><Head title="Create a household"/><Link href="/setup" class="help inline-block hover:underline">← Back to household setup</Link><h1 class="mt-5">Create a household</h1><p class="mt-3 text-muted">All fields are required unless marked Optional.</p><form class="panel mt-6 space-y-5 p-6" novalidate @submit.prevent="save"><div v-if="form.hasErrors" ref="errors" tabindex="-1" role="alert" class="rounded border border-orange-200 bg-orange-50 p-3 text-warning"><p class="font-medium">Review these fields:</p><a v-for="(error,field) in form.errors" :key="field" :href="'#create-'+field" class="mt-1 block underline" @click.prevent="($event.currentTarget as HTMLAnchorElement).closest('form')?.querySelector<HTMLElement>('#create-'+field)?.focus()">{{error}}</a></div><div v-for="[field,label,max] in [['name','Household name',100],['nickname','Your nickname',80],['timezone','Your timezone',100]]" :key="String(field)" class="field"><label :for="'create-'+field">{{label}}</label><SelectField v-if="field==='timezone'" id="create-timezone" v-model="form.timezone" searchable :options="timezones" required/><input v-else :id="'create-'+field" v-model="form[field as 'name'|'nickname'|'timezone']" required :maxlength="Number(max)" :aria-invalid="form.errors[field as 'name'|'nickname'|'timezone']?'true':undefined" :aria-describedby="form.errors[field as 'name'|'nickname'|'timezone']?'create-error-'+field:undefined" :class="form.errors[field as 'name'|'nickname'|'timezone']?'border-orange-600!':''" @blur="blur(field as 'name'|'nickname'|'timezone')"/><p v-if="form.errors[field as 'name'|'nickname'|'timezone']" :id="'create-error-'+field" class="help text-warning">⚠ {{form.errors[field as 'name'|'nickname'|'timezone']}}</p></div><div class="rounded bg-ground p-4"><h2 class="text-base">After you create it</h2><p class="help mt-2">You’ll be the owner. Add accounts, bills and income, then invite the people you share money with. Everyone in the household can edit its financial records.</p></div><div class="flex justify-end gap-2 border-t border-line pt-4"><Link href="/setup" class="btn">Cancel</Link><button class="btn-primary" :disabled="form.processing"><LoaderCircle v-if="form.processing" :size="16" class="animate-spin"/>{{form.processing?'Creating…':form.hasErrors?'Try again':'Create household'}}</button></div></form><ConfirmDialog :open="discard" title="Leave without creating a household?" confirm-label="Discard and leave" @cancel="discard=false" @confirm="leave">The details you entered have not been saved.</ConfirmDialog></SetupLayout></template>
